import type { MiddlewareHandler } from 'hono';
import type { AppEnv } from '../app';

/**
 * Gives every request a fresh `crypto.randomUUID()`: `c.get('requestId')` and the `x-request-id`
 * response header. Always generated by the server; an incoming `x-request-id` is ignored, so a
 * client cannot choose the id its requests are logged under.
 */
export function requestId(): MiddlewareHandler<AppEnv> {
  return async (c, next) => {
    const id = crypto.randomUUID();
    c.set('requestId', id);
    c.header('x-request-id', id);
    await next();
  };
}
